// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, address actor) public {
        t1 = bound(t1, 1, type(uint64).max - 2);
        vm.assume(actor != address(0));
        vm.deal(actor, 20 ether);

        // First call at time t1: succeeds in both P and M
        vm.warp(t1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Rule: the very next block at time t1+1 must REVERT,
        // because pastBlockTime was advanced past t1 (stored t1+1).
        vm.warp(t1 + 1);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}
